// =============================================================================
// scripts/build-edge-functions.mjs
// Bundles selected Vercel handlers (api/*.js) UNCHANGED into Supabase Edge
// Functions, using supabase/functions/_shared/node-adapter.ts to translate
// Request/Response <-> (req, res). One code path, two hosts: fix a bug in
// api/*.js, re-run this, redeploy.
//
//   node scripts/build-edge-functions.mjs            build all
//   node scripts/build-edge-functions.mjs college-quiz
//
// Output (COMMITTED, generated - do not edit):
//   supabase/functions/<name>/index.ts
// Deploy:  supabase functions deploy <name> --no-verify-jwt   (handlers do their own auth)
// =============================================================================
import { build } from "esbuild";
import { builtinModules } from "node:module";
import { mkdir } from "node:fs/promises";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const fnDir = path.join(root, "supabase/functions");

const TARGETS = {
  "college-quiz": "api/college-quiz.js", // /api/colleges, /api/delete-quiz, /api/reports, lesson comments
  "upload-quiz": "api/upload-quiz.js",
  "ai-chat": "api/ai-agent/chat.js",
  "ai-usage": "api/ai-agent/usage.js",
  "ai-bot": "api/ai-agent/bot.js", // Telegram webhook (re-register with setWebhook after deploy)
};

const builtins = new Set(builtinModules.flatMap((m) => [m, `node:${m}`]));
const nodePrefix = {
  name: "node-prefix",
  setup(b) {
    b.onResolve({ filter: /^(node:)?[a-z_]+(\/[a-z_]+)?$/ }, (args) =>
      builtins.has(args.path) ? { path: args.path.startsWith("node:") ? args.path : `node:${args.path}`, external: true } : null);
  },
};

const BANNER = `// GENERATED by scripts/build-edge-functions.mjs from {SRC} - DO NOT EDIT.
import process from "node:process";
import { Buffer } from "node:buffer";
import { createRequire } from "node:module";
globalThis.process ??= process;
globalThis.Buffer ??= Buffer;
const require = createRequire(import.meta.url);`;

const only = process.argv.slice(2);
for (const [name, src] of Object.entries(TARGETS)) {
  if (only.length && !only.includes(name)) continue;
  await mkdir(path.join(fnDir, name), { recursive: true });
  await build({
    stdin: {
      contents: [
        `import ${JSON.stringify(path.join(fnDir, "_shared/env-shim.ts"))};`,
        `import handler from ${JSON.stringify(path.join(root, src))};`,
        `import { serveNode } from ${JSON.stringify(path.join(fnDir, "_shared/node-adapter.ts"))};`,
        `Deno.serve(serveNode(handler));`,
      ].join("\n"),
      resolveDir: root,
      sourcefile: `${name}-entry.js`,
      loader: "js",
    },
    outfile: path.join(fnDir, name, "index.ts"),
    bundle: true,
    format: "esm",
    platform: "node",
    target: "es2022",
    plugins: [nodePrefix],
    banner: { js: BANNER.replace("{SRC}", src) },
    logLevel: "warning",
    legalComments: "none",
    minify: true,
  });
  console.log("built", name);
}
